package com.graduation.lab.domain; import org.springframework.boot.CommandLineRunner;import org.springframework.core.annotation.Order;import org.springframework.context.annotation.*;
@org.springframework.context.annotation.Profile({"dev","test","ci"}) @Configuration public class ProjectDataSeed{@Bean @Order(10) CommandLineRunner seedProject(LaboratoryRepository labs){return args->{if(labs.count()==0){var x=new Laboratory();x.setName("光电综合实验室");x.setBuilding("理科楼");x.setRoom("A402");x.setCapacity(28);x.setEquipment("示波器、激光器、光谱仪、光学平台");x.setOpenTime("08:00");x.setCloseTime("21:30");x.setStatus("OPEN");labs.save(x);}};}}
